// State Variables
let currentLabAttack = LAB_ATTACKS[0];
let labRunning = false;
let currentLabCategory = "all";
let labSearchQuery = "";
let labRunToken = 0;

function wait(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function typeLine(container, text, cls) {
  const d = document.createElement("div");
  d.className = "ln " + cls;
  d.textContent = text;
  container.appendChild(d);
  container.scrollTop = container.scrollHeight;
}

function setLabStep(i) {
  const count = currentLabAttack.steps.length;
  for (let k = 0; k < count; k++) {
    const pip = document.getElementById(`lab-pip-${k}`);
    const pipTitle = document.getElementById(`lab-piptitle-${k}`);
    if (pip) pip.classList.toggle("live", k === i);
    if (pipTitle) pipTitle.classList.toggle("live", k === i);
  }
  const label = document.getElementById("labStepLabel");
  if (label) label.textContent = currentLabAttack.steps[i] || "—";
}

function resetLabTerminals() {
  const aB = document.getElementById("attackerBody");
  const vB = document.getElementById("victimBody");
  const mB = document.getElementById("monitorBody");
  if (aB) aB.innerHTML = '<span class="ph">attacker@kali:~$ _</span>';
  if (vB) vB.innerHTML = '<span class="ph">victim@target:~$ _</span>';
  if (mB) mB.innerHTML = '<span class="ph">snort -i eth0 -A console -q</span>';
  const label = document.getElementById("labStepLabel");
  if (label) label.textContent = "—";
}

function buildStepsBar(steps) {
  const bar = document.getElementById("labStepsBar");
  if (!bar) return;
  bar.innerHTML = "";
  steps.forEach((s, i) => {
    const pip = document.createElement("div");
    pip.className = "step-pip";
    pip.innerHTML = `
      <div class="pip-circle" id="lab-pip-${i}">${i + 1}</div>
      <div class="pip-body">
        <div class="pip-title" id="lab-piptitle-${i}">${s}</div>
      </div>
      ${i < steps.length - 1 ? '<div class="pip-line"></div>' : ''}
    `;
    bar.appendChild(pip);
  });
}

function buildStepList(elId, steps) {
  const el = document.getElementById(elId);
  if (!el) return;
  el.innerHTML = steps.map(s => `<li><span class="sn">${s.n}</span><span>${s.text}</span></li>`).join("");
}

function buildRulesGrid(rules) {
  const grid = document.getElementById("labRulesGrid");
  if (!grid) return;
  grid.innerHTML = rules.map(r => {
    const safeSnort = (r.snort || "").replace(/"/g, '&quot;');
    return `
      <div class="rule-card">
        <div class="rule-top-row">
          <span class="rule-sid">${r.sid}</span>
          <span class="rule-sev sev-${r.sev}">${r.sev.toUpperCase()}</span>
        </div>
        <div class="rule-name">${r.name}</div>
        <div class="rule-snort-wrapper">
          <code class="rule-snort">${r.snort}</code>
          <button class="rule-copy-btn" onclick="copySnortRule('${safeSnort}')" title="Copy Snort Rule Definition">
            <svg viewBox="0 0 24 24" width="13" height="13" stroke="currentColor" fill="none" stroke-width="2">
              <rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect>
              <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path>
            </svg>
            <span>Copy</span>
          </button>
        </div>
        <div class="rule-desc">${r.desc}</div>
      </div>
    `;
  }).join("");
}

function copySnortRule(text) {
  const decoded = text.replace(/&quot;/g, '"');
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(decoded).then(() => {
      if (typeof showToast === "function") {
        showToast("✓ Snort alert rule copied to clipboard!");
      }
    }).catch(() => fallbackCopy(decoded));
  } else {
    fallbackCopy(decoded);
  }
}

function fallbackCopy(text) {
  const ta = document.createElement("textarea");
  ta.value = text;
  document.body.appendChild(ta);
  ta.select();
  document.execCommand("copy");
  document.body.removeChild(ta);
  if (typeof showToast === "function") {
    showToast("✓ Snort alert rule copied to clipboard!");
  }
}

function updateDossierCrossLink(labId) {
  const linkBtn = document.getElementById("labJumpDossierBtn");
  if (!linkBtn) return;
  const learningId = LAB_TO_LEARNING_MAP[labId];
  if (learningId) {
    linkBtn.style.display = "inline-flex";
    linkBtn.onclick = () => {
      if (typeof switchAppMode === "function") {
        switchAppMode("learning");
        if (typeof loadAttack === "function") {
          loadAttack(learningId);
        }
      }
    };
  } else {
    linkBtn.style.display = "none";
  }
}

function selectLabAttack(id, updateHash = true) {
  if (labRunning) {
    labRunToken++;
    labRunning = false;
    const runBtn = document.getElementById("labRunBtn");
    if (runBtn) {
      runBtn.disabled = false;
      runBtn.classList.remove("running");
      runBtn.innerHTML = '▶ Run Simulation';
    }
  }

  const found = LAB_ATTACKS.find(a => a.id === id);
  if (!found) return;
  currentLabAttack = found;

  // Active state on attack selection buttons
  document.querySelectorAll(".lab-attack-btn").forEach(btn => {
    btn.classList.toggle("active", btn.dataset.id === id);
  });

  // Update Hero & Descriptions
  const titleEl = document.getElementById("labAttackTitle");
  if (titleEl) titleEl.textContent = currentLabAttack.name;

  const subtitleEl = document.getElementById("labSubtitle");
  if (subtitleEl) subtitleEl.textContent = currentLabAttack.subtitle;

  const aIP = document.getElementById("labAIP");
  if (aIP) aIP.textContent = currentLabAttack.aIP;
  const vIP = document.getElementById("labVIP");
  if (vIP) vIP.textContent = currentLabAttack.vIP;
  const mIP = document.getElementById("labMIP");
  if (mIP) mIP.textContent = currentLabAttack.mIP;

  const aConn = document.getElementById("labAConn");
  if (aConn) aConn.textContent = currentLabAttack.aConn;
  const vConn = document.getElementById("labVConn");
  if (vConn) vConn.textContent = currentLabAttack.vConn;
  const mConn = document.getElementById("labMConn");
  if (mConn) mConn.textContent = currentLabAttack.mConn;

  const aDesc = document.getElementById("labADesc");
  if (aDesc) aDesc.innerHTML = currentLabAttack.aDesc;
  const vDesc = document.getElementById("labVDesc");
  if (vDesc) vDesc.innerHTML = currentLabAttack.vDesc;
  const mDesc = document.getElementById("labMDesc");
  if (mDesc) mDesc.innerHTML = currentLabAttack.mDesc;

  // Render Step pipeline & Details
  buildStepsBar(currentLabAttack.steps);
  buildStepList("sdAttacker", currentLabAttack.aSteps);
  buildStepList("sdVictim", currentLabAttack.vSteps);
  buildStepList("sdMonitor", currentLabAttack.mSteps);

  // Render Snort Alert Rules
  buildRulesGrid(currentLabAttack.alertRules);

  // Update cross link
  updateDossierCrossLink(currentLabAttack.id);

  // Reset terminal displays
  resetLabTerminals();

  if (updateHash) {
    window.location.hash = `lab?attack=${currentLabAttack.id}`;
  }
}

async function runLabSimulation() {
  if (labRunning) return;
  labRunning = true;
  labRunToken++;
  const thisToken = labRunToken;

  const runBtn = document.getElementById("labRunBtn");
  if (runBtn) {
    runBtn.disabled = true;
    runBtn.classList.add("running");
    runBtn.innerHTML = '<span class="pulse-dot"></span> Simulating...';
  }

  resetLabTerminals();
  const aB = document.getElementById("attackerBody");
  const vB = document.getElementById("victimBody");
  const mB = document.getElementById("monitorBody");
  if (aB) aB.innerHTML = "";
  if (vB) vB.innerHTML = "";
  if (mB) mB.innerHTML = "";

  const maxLen = Math.max(
    currentLabAttack.a.length,
    currentLabAttack.v.length,
    currentLabAttack.m.length
  );
  const stepCount = currentLabAttack.steps.length;

  for (let i = 0; i < maxLen; i++) {
    if (thisToken !== labRunToken) break;
    setLabStep(Math.min(Math.floor((i / maxLen) * stepCount), stepCount - 1));

    if (currentLabAttack.a[i]) {
      typeLine(aB, currentLabAttack.a[i][0], currentLabAttack.a[i][1]);
      await wait(140);
    }
    if (thisToken !== labRunToken) break;
    if (currentLabAttack.v[i]) {
      typeLine(vB, currentLabAttack.v[i][0], currentLabAttack.v[i][1]);
      await wait(140);
    }
    if (thisToken !== labRunToken) break;
    if (currentLabAttack.m[i]) {
      typeLine(mB, currentLabAttack.m[i][0], currentLabAttack.m[i][1]);
      await wait(140);
    }
    if (thisToken !== labRunToken) break;
    await wait(360);
  }

  if (thisToken === labRunToken) {
    setLabStep(stepCount - 1);
  }

  labRunning = false;
  if (runBtn) {
    runBtn.disabled = false;
    runBtn.classList.remove("running");
    runBtn.innerHTML = '▶ Run Simulation';
  }
}

function resetLabSimulation() {
  labRunToken++;
  labRunning = false;
  const runBtn = document.getElementById("labRunBtn");
  if (runBtn) {
    runBtn.disabled = false;
    runBtn.classList.remove("running");
    runBtn.innerHTML = '▶ Run Simulation';
  }
  resetLabTerminals();
  buildStepsBar(currentLabAttack.steps);
  const label = document.getElementById("labStepLabel");
  if (label) label.textContent = "—";
}

function renderLabAttackButtons() {
  const container = document.getElementById("labAttackBtns");
  if (!container) return;
  container.innerHTML = "";

  const filtered = LAB_ATTACKS.filter(a => {
    const cat = LAB_CATEGORY_MAP[a.id] || "other";
    const matchesCategory = currentLabCategory === "all" || cat === currentLabCategory;
    const matchesSearch = !labSearchQuery || 
      a.name.toLowerCase().includes(labSearchQuery) || 
      a.subtitle.toLowerCase().includes(labSearchQuery) ||
      a.id.toLowerCase().includes(labSearchQuery);
    return matchesCategory && matchesSearch;
  });

  if (filtered.length === 0) {
    container.innerHTML = '<div class="lab-empty-filter">No simulation labs match this category or search filter.</div>';
    return;
  }

  filtered.forEach(a => {
    const btn = document.createElement("button");
    btn.className = "lab-attack-btn" + (a.id === currentLabAttack.id ? " active" : "");
    btn.dataset.id = a.id;
    btn.innerHTML = `
      <span class="lab-btn-indicator"></span>
      <span class="lab-btn-name">${a.name}</span>
    `;
    btn.onclick = () => selectLabAttack(a.id);
    container.appendChild(btn);
  });
}

function renderLabCategoryPills() {
  const container = document.getElementById("labCategoryPills");
  if (!container) return;
  container.innerHTML = "";

  LAB_CATEGORIES.forEach(cat => {
    const pill = document.createElement("button");
    pill.className = "lab-cat-pill" + (cat.id === currentLabCategory ? " active" : "");
    pill.dataset.category = cat.id;
    pill.innerHTML = `<span>${cat.label}</span><span class="lab-cat-count">${cat.count}</span>`;
    pill.onclick = () => {
      currentLabCategory = cat.id;
      document.querySelectorAll(".lab-cat-pill").forEach(p => p.classList.remove("active"));
      pill.classList.add("active");
      renderLabAttackButtons();
    };
    container.appendChild(pill);
  });
}

function initLabEvents() {
  renderLabCategoryPills();
  renderLabAttackButtons();

  const runBtn = document.getElementById("labRunBtn");
  if (runBtn) runBtn.onclick = runLabSimulation;

  const resetBtn = document.getElementById("labResetBtn");
  if (resetBtn) resetBtn.onclick = resetLabSimulation;

  const searchInput = document.getElementById("labSearchInput");
  const clearSearchBtn = document.getElementById("labClearSearchBtn");

  if (searchInput) {
    searchInput.addEventListener("input", (e) => {
      labSearchQuery = e.target.value.trim().toLowerCase();
      if (clearSearchBtn) {
        clearSearchBtn.style.display = labSearchQuery.length > 0 ? "block" : "none";
      }
      renderLabAttackButtons();
    });
  }

  if (clearSearchBtn) {
    clearSearchBtn.addEventListener("click", () => {
      if (searchInput) {
        searchInput.value = "";
        labSearchQuery = "";
        clearSearchBtn.style.display = "none";
        renderLabAttackButtons();
        searchInput.focus();
      }
    });
  }
}

function onLabModeActivated() {
  // Check if hash has a specific attack
  const hash = window.location.hash.replace("#", "");
  if (hash.startsWith("lab")) {
    const parts = hash.split("?");
    if (parts.length > 1) {
      const params = new URLSearchParams(parts[1]);
      const attackId = params.get("attack");
      if (attackId && LAB_ATTACKS.some(a => a.id === attackId)) {
        selectLabAttack(attackId, false);
        return;
      }
    }
  }
  selectLabAttack(currentLabAttack.id, false);
}

// Global hook to launch lab simulation from Learning Mode or search
window.openLabSimulation = function(labId) {
  if (typeof switchAppMode === "function") {
    switchAppMode("lab");
  }
  setTimeout(() => {
    selectLabAttack(labId, true);
    // Smooth scroll to top
    const labLayout = document.getElementById("lab-layout");
    if (labLayout) labLayout.scrollIntoView({ behavior: "smooth" });
  }, 50);
};

window.copySnortRule = copySnortRule;
window.selectLabAttack = selectLabAttack;
window.onLabModeActivated = onLabModeActivated;

// Initialize on DOM load
document.addEventListener("DOMContentLoaded", () => {
  initLabEvents();
  selectLabAttack(currentLabAttack.id, false);
});